// BuildX PC – 21 màn hình phía nhân viên (SC22–SC42, UC12–UC22)
(function () {
  "use strict";
  const { COMBOS, COMBO_OPTS, FEES, ORDER, CAT, STATUSES, PLAN, ROLES } = window.BX;
  const E = window.BXE, S = E.S, A = window.BXA;
  const { $, $$, fmt, tr, esc, toast, tag, stPill, payPill, checkHtml, availPill, add, rerender } = A;
  const byId = E.byId, go = (h) => (location.hash = h);
  const sellable = (cat) => E.P.filter((p) => p.cat === cat && !p.ref);
  const partsList = (cfg) => ORDER.filter((s) => cfg[s].id && cfg[s].mode !== "skip").map((s) => byId(cfg[s].id).id + (s === "ram" && cfg.ram.qty > 1 ? "×" + cfg.ram.qty : "") + (cfg[s].mode === "own" ? "(KH)" : "")).concat(cfg.extras.map((e) => e.id)).join(" · ");
  const lineTitle = (l) => l.title || byId(l.id).n + (l.qty > 1 ? " ×" + l.qty : "");
  const head = (h, sub, sc, ucs) => `<div class="row between"><div><h1>${h}</h1><p class="muted small">${sub} ${tag(sc, ucs)}</p></div></div>`;
  const TECHS = () => S.staffUsers.filter((u) => u.role === "Kỹ thuật viên" && u.on).map((u) => u.name).concat(["Ngô Văn Long"]);

  // ================= SC22 – Bán tại quầy (POS) =================
  S.posMode = false;
  add("SC22", "pos", "Bán tại quầy (POS)", "UC12", "admin", () => {
    const P = S.pos, sub = P.lines.reduce((t, l) => t + E.linePrice(l), 0), limit = Math.min(500000, sub * 0.02), needApprove = P.disc > limit && !P.approved;
    return `${head("Bán tại quầy", "Dùng chung giá và luật tương thích với website. Giảm giá ngoài chính sách (> 2% hoặc > 500.000đ) cần quản lý duyệt.", "SC22", "UC12")}
    <div class="side" style="margin-top:12px"><div class="stack"><div class="panel"><div class="row" style="flex-wrap:nowrap"><input id="ps" type="text" placeholder="Tìm sản phẩm: tên, mã, socket…" aria-label="Tìm sản phẩm"></div><div id="pr" class="stack" style="gap:6px;margin-top:8px"></div></div>
      <div class="panel"><h3>Mở công cụ cấu hình cho khách</h3><div class="row">${COMBOS.map((c) => `<button class="btn sm plain" type="button" data-cb="${c.key}">+ ${c.name}</button>`).join("")}<button class="btn sm" type="button" id="bb">Build PC hộ khách</button><a class="btn sm ghost" href="#/upgrade">Nâng cấp PC</a></div><p class="xs muted" style="margin-top:6px">Build PC hộ khách mở cùng công cụ của website; ở bước tổng kết bấm "Thêm vào đơn tại quầy".</p></div></div>
    <div class="panel stack"><h3>Đơn tại quầy</h3>
      <div class="row" style="flex-wrap:nowrap"><input id="cph" type="tel" placeholder="SĐT khách" value="${esc(P.cust ? P.cust.phone : "")}" aria-label="SĐT khách"><button class="btn sm plain" type="button" id="fc">Tìm / tạo</button></div>${P.cust ? `<span class="small">Khách: <b>${esc(P.cust.name)}</b>${P.cust.isNew ? ' <span class="pill acc">Tài khoản mới</span>' : ""}</span>` : ""}
      ${P.lines.map((l, i) => `<div class="row between small" style="border-bottom:1px solid var(--line);padding-bottom:6px"><span style="flex:1;min-width:0"><b>${esc(lineTitle(l))}</b>${l.cfg ? `<br><span class="xs muted">${partsList(l.cfg)}</span><br><label class="xs"><input type="checkbox" data-asm="${i}" ${l.asm !== "none" ? "checked" : ""} ${E.canAssemble(l.cfg) ? "" : "disabled"}> Lắp ráp ${fmt(E.hasOwn(l.cfg) ? FEES.asmOwn : FEES.asm)}</label>` : ""}</span><span class="price">${fmt(E.linePrice(l))}</span><button class="btn sm plain" type="button" data-rm="${i}" aria-label="Xóa">×</button></div>`).join("") || '<p class="small muted">Chưa có sản phẩm.</p>'}
      <div class="row between"><span class="small">Tạm tính</span><span class="price">${fmt(sub)}</span></div>
      <div class="row between"><label for="dc" class="small">Giảm giá</label><input id="dc" type="number" min="0" step="10000" value="${P.disc}" style="width:130px"></div>
      ${needApprove ? `<div class="notice warn small">Giảm ${fmt(P.disc)} vượt chính sách (${fmt(limit)}). <button class="btn sm" type="button" id="ap">Quản lý duyệt</button></div>` : P.disc ? `<span class="xs muted">${P.approved ? "Quản lý đã duyệt, đã lưu vết." : "Trong chính sách."}</span>` : ""}
      <div class="row between"><b>Khách trả</b><span class="price big">${fmt(sub - P.disc)}</span></div>
      <div class="chips">${["Tiền mặt", "Chuyển khoản", "Thẻ"].map((m) => `<button type="button" class="chip" data-pm="${m}" aria-pressed="${P.pay === m}">${m}</button>`).join("")}</div>
      <button class="btn" type="button" id="pay" ${!P.lines.length || !P.cust || needApprove ? "disabled" : ""}>Thu tiền & in hóa đơn</button>${!P.cust ? '<span class="xs muted">Nhập SĐT khách để tạo đơn.</span>' : ""}<div id="inv"></div></div></div>`;
  }, () => {
    const P = S.pos;
    const draw = () => { const q = $("#ps").value.toLowerCase(); $("#pr").innerHTML = q.length < 2 ? '<p class="xs muted">Gõ ít nhất 2 ký tự.</p>' : E.P.filter((p) => !p.ref && (p.n + p.id + (p.socket || "")).toLowerCase().includes(q)).slice(0, 8).map((p) => `<div class="row between small"><span>${p.id} · ${esc(p.n)} ${availPill(p)}</span><span class="row"><span class="price">${fmt(p.price)}</span><button class="btn sm plain" type="button" data-add="${p.id}">Thêm</button></span></div>`).join(""); $$("[data-add]").forEach((b) => (b.onclick = () => { const ex = P.lines.find((l) => l.type === "part" && l.id === b.dataset.add); if (ex) ex.qty++; else P.lines.push({ type: "part", id: b.dataset.add, qty: 1 }); rerender(); })); };
    $("#ps").oninput = draw; draw();
    $$("[data-cb]").forEach((b) => (b.onclick = () => { const c = COMBOS.find((x) => x.key === b.dataset.cb); P.lines.push({ type: "pc", title: c.name, src: "combo", cfg: E.cfgFromCombo(c.key), asm: "shop" }); rerender(); }));
    $("#bb").onclick = () => { S.posMode = true; S.build = E.emptyCfg(); S.buildStep = 0; S.buildSrc = null; go("#/builder"); };
    $$("[data-rm]").forEach((b) => (b.onclick = () => { P.lines.splice(+b.dataset.rm, 1); rerender(); }));
    $$("[data-asm]").forEach((b) => (b.onchange = () => { P.lines[+b.dataset.asm].asm = b.checked ? "shop" : "none"; rerender(); }));
    $("#dc").onchange = (e) => { P.disc = Math.max(0, +e.target.value || 0); P.approved = false; rerender(); };
    const ap = $("#ap"); if (ap) ap.onclick = () => { if (S.staff.role !== "Quản lý" && prompt("Mã duyệt của quản lý (demo: 1234)") !== "1234") return toast("Sai mã duyệt"); P.approved = true; E.log(`Duyệt giảm giá ngoài chính sách ${fmt(P.disc)} tại quầy`, "POS"); rerender(); };
    $$("[data-pm]").forEach((b) => (b.onclick = () => { P.pay = b.dataset.pm; rerender(); }));
    $("#fc").onclick = () => { const ph = $("#cph").value.trim(); if (!ph) return; const prev = S.orders.find((o) => o.cust.phone.replace(/\s/g, "") === ph.replace(/\s/g, "")); P.cust = prev ? { ...prev.cust } : { name: prompt("Tên khách mới", "Khách lẻ") || "Khách lẻ", phone: ph, addr: "Mua tại cửa hàng", isNew: true }; rerender(); };
    const pay = $("#pay"); if (pay) pay.onclick = () => {
      const o = E.createOrder({ cust: { name: P.cust.name, phone: P.cust.phone, addr: P.cust.addr }, lines: E.clone(P.lines), ship: { mode: "pickup" }, coupon: P.disc ? { cp: { code: "GIẢM TẠI QUẦY", used: 0 }, amt: P.disc } : null, payMethod: P.pay, channel: "Tại quầy" });
      o.risk = { score: 0, reasons: [], needVerify: false, verified: true };
      E.gatewayPaid(o, o.total); o.log[o.log.length - 1].who = S.staff.name; o.log[o.log.length - 1].msg = `Thu ${fmt(o.total)} tại quầy (${P.pay})`;
      E.confirmOrder(o);
      if (o.status === "Đã xác nhận") { E.toNext(o); if (o.status === "Đóng gói") { E.ship(o, "Giao tại quầy"); E.complete(o); } }
      const msg = o.status === "Hoàn tất" ? "Đã xuất kho và giao tại quầy." : o.status === "Lắp ráp & QC" ? "Đã tạo phiếu lắp ráp." : "Thiếu hàng: đơn chuyển Chờ hàng.";
      S.pos = { cust: null, lines: [], disc: 0, approved: false, pay: "Tiền mặt" };
      rerender(); $("#inv").innerHTML = `<div class="notice ok small"><b>Hóa đơn ${o.id}</b> · ${fmt(o.total)} · ${esc(o.pay.method)}<br>${msg} <a href="#/order/${o.id}">Mở đơn</a></div>`;
    };
  });

  // ================= SC23 – Danh sách lead =================
  const LEAD_ST = ["Mới", "Đang tư vấn", "Đã gửi báo giá", "Đã chốt", "Mất"];
  add("SC23", "leads", "Danh sách lead", "UC13", "admin", () => {
    const closed = S.leads.filter((l) => ["Đã chốt", "Mất"].includes(l.st)), won = closed.filter((l) => l.st === "Đã chốt").length;
    const rate = S.leads.length ? Math.round((S.leads.filter((l) => l.st === "Đã chốt").length / S.leads.length) * 100) : 0;
    return `${head("Lead & tư vấn", `Tỷ lệ lead thành đơn: <b>${rate}%</b> (giả định mô hình 20%).`, "SC23", "UC13")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Khách</th><th>Kênh</th><th>Nhu cầu</th><th>Trạng thái</th><th>Ghi chú</th><th></th></tr></thead><tbody>${S.leads.map((l, i) => `<tr><td class="mono xs">${l.id}<br><span class="muted">${l.ago}</span></td><td><b>${esc(l.name)}</b><br><span class="xs muted">${esc(l.phone)}</span></td><td class="small">${esc(l.src)}</td><td class="small">${esc(l.need)}</td><td><select data-st="${i}" style="width:auto">${LEAD_ST.map((s) => `<option ${s === l.st ? "selected" : ""}>${s}</option>`).join("")}</select></td><td><input type="text" data-nt="${i}" value="${esc(l.note)}" aria-label="Ghi chú"></td><td><a class="btn sm" href="#/quote/${l.id}">Báo giá</a></td></tr>`).join("")}</tbody></table></div>
    <form class="panel" id="fl" style="margin-top:16px"><h3>Thêm lead (từ Zalo, Facebook, livestream, gọi điện)</h3><div class="grid4"><div class="field"><label for="ln">Tên</label><input id="ln" type="text" required></div><div class="field"><label for="lp">SĐT</label><input id="lp" type="tel" required></div><div class="field"><label for="ls">Kênh</label><select id="ls"><option>Zalo OA</option><option>Facebook</option><option>Livestream</option><option>Gọi điện</option><option>Tại cửa hàng</option></select></div><div class="field"><label for="lq">Nhu cầu</label><input id="lq" type="text" required></div></div><button class="btn sm" type="submit">Thêm lead</button></form>`;
  }, () => {
    $$("[data-st]").forEach((s) => (s.onchange = () => { S.leads[+s.dataset.st].st = s.value; E.log("Cập nhật lead → " + s.value, S.leads[+s.dataset.st].id); rerender(); }));
    $$("[data-nt]").forEach((s) => (s.onchange = () => { S.leads[+s.dataset.nt].note = s.value; }));
    $("#fl").onsubmit = (e) => { e.preventDefault(); S.leads.unshift({ id: "L-" + (1032 + S.leads.length), name: $("#ln").value, phone: $("#lp").value, src: $("#ls").value, need: $("#lq").value, st: "Mới", note: "", ago: "vừa xong" }); rerender(); };
  });

  // ================= SC24 – Tạo & gửi báo giá =================
  S.quoteCfg = null;
  add("SC24", "quote", "Tạo & gửi báo giá", "UC13", "admin", (lid) => {
    const lead = S.leads.find((l) => l.id === lid) || S.leads.find((l) => l.st === "Đang tư vấn") || S.leads[0];
    if (!S.quoteCfg || S.quoteCfg.lead !== lead.id) S.quoteCfg = { lead: lead.id, cfg: E.cfgFromCombo("esports") };
    const c = S.quoteCfg.cfg, rs = E.evalRules(c), q = S.quotes.filter((x) => x.lead === lead.id);
    return `${head("Báo giá cho " + esc(lead.name), `${esc(lead.id)} · ${esc(lead.need)} · Dùng chung bộ luật tương thích với website: mỗi ô chỉ liệt kê linh kiện hợp.`, "SC24", "UC13")}
    <div class="side" style="margin-top:12px"><div class="stack"><div class="panel"><div class="row">Nạp combo: ${COMBOS.map((cb) => `<button class="btn sm plain" type="button" data-cb="${cb.key}">${cb.name}</button>`).join("")}</div></div>
      <div class="tbl"><table><thead><tr><th>Thành phần</th><th>Linh kiện (chỉ hiện loại tương thích)</th><th class="num">Giá</th></tr></thead><tbody>${ORDER.map((s) => { const opts = sellable(s).filter((p) => p.id === c[s].id || !E.tryPart(c, s, p.id).bad.length); return `<tr><td><b>${CAT[s]}</b></td><td><select data-s="${s}" aria-label="${CAT[s]}">${opts.map((p) => `<option value="${p.id}" ${p.id === c[s].id ? "selected" : ""}>${esc(p.n)}${E.avail(p.id) ? "" : " (đặt trước)"}</option>`).join("")}</select><span class="xs muted">${opts.length}/${sellable(s).length} tương thích</span></td><td class="num">${fmt(byId(c[s].id).price * c[s].qty)}</td></tr>`; }).join("")}</tbody></table></div></div>
    <div class="panel stack"><span class="lbl">Tổng báo giá (chưa gồm lắp ráp)</span><span class="price big">${fmt(E.cfgPrice(c))}</span>${checkHtml(rs.filter((r) => r.lv !== "ok"))}${E.worst(rs) === "ok" ? '<div class="notice ok small">Đạt toàn bộ luật tương thích.</div>' : ""}
      <div class="field"><label for="msg">Lời nhắn</label><textarea id="msg">Cấu hình này đạt trên 240 FPS Valorant ở 1080p, còn dư nguồn để lên RTX 5060.</textarea></div>
      <button class="btn" type="button" id="send" ${E.worst(rs) === "bad" ? "disabled" : ""}>Gửi link báo giá (hiệu lực 48 giờ)</button>
      ${q.map((x) => `<div class="notice small"><b>${x.id}</b> · ${fmt(x.price)} · hết hạn ${x.exp}<br><span class="mono xs">buildx.vn/q/${x.id}</span><br>${x.ordered ? `Khách đã đặt: <a href="#/order/${x.ordered}">${x.ordered}</a>` : `<button class="btn sm plain" type="button" data-ord="${x.id}">Mô phỏng: khách đặt từ link</button>`}</div>`).join("")}</div></div>`;
  }, (lid) => {
    const lead = S.leads.find((l) => l.id === lid) || S.leads.find((l) => l.st === "Đang tư vấn") || S.leads[0], c = S.quoteCfg.cfg;
    $$("[data-cb]").forEach((b) => (b.onclick = () => { S.quoteCfg.cfg = E.cfgFromCombo(b.dataset.cb); rerender(); }));
    $$("[data-s]").forEach((s) => (s.onchange = () => { c[s.dataset.s] = { mode: "buy", id: s.value, qty: c[s.dataset.s].qty }; ORDER.forEach((o) => { if (o !== s.dataset.s && E.tryPart(c, o, c[o].id).bad.length) { const alt = sellable(o).find((p) => !E.tryPart(c, o, p.id).bad.length); if (alt) c[o] = { mode: "buy", id: alt.id, qty: c[o].qty }; } }); rerender(); }));
    $("#send").onclick = () => { const id = "Q-" + (2208 + S.quotes.length); S.quotes.unshift({ id, lead: lead.id, cfg: E.clone(c), price: E.cfgPrice(c), exp: "18/04/2027 10:00" }); lead.st = "Đã gửi báo giá"; E.log("Gửi link báo giá 48 giờ", id); toast("Đã gửi buildx.vn/q/" + id + " qua " + lead.src); rerender(); };
    $$("[data-ord]").forEach((b) => (b.onclick = () => { const q = S.quotes.find((x) => x.id === b.dataset.ord); const o = E.createOrder({ cust: { name: lead.name, phone: lead.phone, addr: "Theo báo giá" }, lines: [{ type: "pc", title: "Cấu hình theo báo giá " + q.id, src: "quote", cfg: E.clone(q.cfg), asm: "shop" }], payMethod: "VNPAY", channel: "Báo giá" }); E.gatewayPaid(o, o.pay.due); q.ordered = o.id; lead.st = "Đã chốt"; rerender(); }));
  });

  // ================= SC25 – Danh sách đơn =================
  S.ordFilter = "Tất cả";
  add("SC25", "orders", "Danh sách đơn", "UC14", "admin", () => {
    const f = S.ordFilter, cnt = (s) => S.orders.filter((o) => o.status === s).length, risky = S.orders.filter((o) => o.status === "Mới" && o.risk.needVerify && !o.risk.verified);
    const list = S.orders.filter((o) => f === "Tất cả" || (f === "Cần xác minh" ? risky.includes(o) : o.status === f));
    return `${head("Đơn hàng", "Đơn website, tại quầy và từ báo giá đi chung một bảng trạng thái.", "SC25", "UC14")}
    <div class="chips" style="margin-top:10px">${["Tất cả", ...STATUSES].map((s) => `<button type="button" class="chip" data-f="${s}" aria-pressed="${f === s}">${s} <span class="mono xs">${s === "Tất cả" ? S.orders.length : cnt(s)}</span></button>`).join("")}<button type="button" class="chip" data-f="Cần xác minh" aria-pressed="${f === "Cần xác minh"}">⚠ Cần xác minh <span class="mono xs">${risky.length}</span></button></div>
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Ngày</th><th>Kênh</th><th>Khách</th><th>Sản phẩm</th><th class="num">Tổng</th><th>Thanh toán</th><th>Rủi ro</th><th>Trạng thái</th></tr></thead><tbody>${list.map((o) => `<tr><td><a class="mono" href="#/order/${o.id}">${o.id}</a></td><td class="small">${E.dstr(o.date)}</td><td class="small">${o.channel}</td><td><b>${esc(o.cust.name)}</b><br><span class="xs muted">${esc(o.cust.phone)}</span></td><td class="small">${esc(o.lines.map(lineTitle).join(", "))}</td><td class="num">${fmt(o.total)}</td><td>${payPill(o.pay)}<br><span class="xs muted">${o.pay.method}</span></td><td><span class="pill ${o.risk.score >= 50 ? (o.risk.verified ? "info" : "bad") : o.risk.score >= 30 ? "warn" : "ok"}">${o.risk.score}${o.risk.verified && o.risk.needVerify ? " ✓" : ""}</span></td><td>${stPill(o.status)}</td></tr>`).join("") || '<tr><td colspan="9" class="muted">Không có đơn.</td></tr>'}</tbody></table></div>`;
  }, () => { $$("[data-f]").forEach((b) => (b.onclick = () => { S.ordFilter = b.dataset.f; rerender(); })); });

  // ================= SC26 – Chi tiết xử lý đơn =================
  add("SC26", "order", "Chi tiết xử lý đơn", "UC14", "admin", (id) => {
    const o = E.findOrder(id) || S.orders.find((x) => x.status === "Mới") || S.orders[0];
    const held = E.units.filter((u) => u.order === o.id);
    const act = [];
    if (o.status === "Mới") { if (o.risk.needVerify && !o.risk.verified) act.push(`<button class="btn sm" type="button" id="vf">Đã gọi xác nhận với khách</button>`); act.push(`<button class="btn" type="button" id="cf">Xác nhận đơn & giữ hàng</button>`); }
    if (o.status === "Đã xác nhận") act.push(`<button class="btn" type="button" id="nx">${o.asm ? "Chuyển xưởng lắp ráp" : "Chuyển đóng gói"}</button>`);
    if (o.status === "Chờ hàng") act.push(`<button class="btn plain" type="button" id="rc">Kiểm tra lại hàng</button><a class="btn sm ghost" href="#/po">Đơn nhập</a>`);
    if (o.status === "Lắp ráp & QC") act.push(`<a class="btn" href="#/ticket/${o.id}">Mở phiếu lắp ráp & QC</a>`);
    if (["Đóng gói", "Đang giao / Chờ nhận"].includes(o.status)) act.push(`<a class="btn" href="#/packing">Đóng gói & bàn giao</a>`);
    if (!["Đang giao / Chờ nhận", "Hoàn tất", "Đã hủy"].includes(o.status)) act.push(`<button class="btn danger" type="button" id="cx">Hủy đơn${o.pay.paid ? " & hoàn tiền" : ""}</button>`);
    return `<a href="#/orders" class="small">← Danh sách đơn</a><div class="row between" style="margin-top:6px"><h1>Đơn ${o.id}</h1>${stPill(o.status)}</div><p class="muted small">${E.tstr(o.date)} · ${o.channel} · ${esc(o.cust.name)} · ${esc(o.cust.phone)} · ${esc(o.cust.addr)} · nhận: ${o.ship.mode === "in" ? "giao nội thành" : o.ship.mode === "out" ? "liên tỉnh" : "tại cửa hàng"} ${tag("SC26", "UC14")}</p>
    <div class="side" style="margin-top:12px"><div class="stack">
      <div class="tbl"><table><thead><tr><th>Sản phẩm</th><th>Linh kiện</th><th class="num">Thành tiền</th></tr></thead><tbody>${o.lines.map((l) => `<tr><td><b>${esc(lineTitle(l))}</b>${l.asm && l.asm !== "none" ? '<br><span class="pill info">Lắp ráp</span>' : ""}</td><td class="mono xs">${l.cfg ? partsList(l.cfg) : l.id || ""}</td><td class="num">${fmt(E.linePrice(l))}</td></tr>`).join("")}${o.disc ? `<tr><td colspan="2">Giảm giá (${esc(o.coupon)})</td><td class="num">−${fmt(o.disc)}</td></tr>` : ""}<tr><td colspan="2"><b>Tổng</b></td><td class="num"><b>${fmt(o.total)}</b></td></tr></tbody></table></div>
      <div class="panel"><h3>Hàng đã giữ theo serial (${held.length})</h3>${held.length ? `<div class="chips">${held.map((u) => `<span class="pill ${u.state === "out" ? "" : "info"} mono">${u.sn}${u.state === "out" ? " · đã xuất" : ""}</span>`).join("")}</div>` : '<p class="small muted">Chưa giữ hàng (đơn Mới chưa xác nhận hoặc đã hủy).</p>'}${o.short.length ? `<div class="notice warn small" style="margin-top:8px">Thiếu: ${o.short.map((s) => esc(byId(s.id).n) + " ×" + s.q).join(", ")}</div>` : ""}</div>
      <div class="panel"><h3>Nhật ký thao tác</h3><div class="stack" style="gap:4px">${o.log.slice().reverse().map((x) => `<div class="small"><span class="mono xs muted">${E.tstr(x.t)}</span> · <b>${esc(x.who)}</b>: ${esc(x.msg)}</div>`).join("")}</div></div></div>
    <div class="panel stack"><h3>Thanh toán</h3><dl class="spec"><dt>Phương thức</dt><dd>${o.pay.method}</dd><dt>Trạng thái</dt><dd>${o.pay.status}</dd><dt>Đã nhận</dt><dd>${fmt(o.pay.paid)}</dd><dt>Còn lại</dt><dd>${fmt(o.total - o.pay.paid)}</dd></dl>${o.pay.method === "COD" ? '<span class="xs muted">COD không có nghĩa là đã thu tiền; chỉ thu đủ khi giao.</span>' : '<span class="xs muted">Chỉ ghi nhận khi máy chủ xác thực IPN hợp lệ từ cổng.</span>'}
      <h3>Rủi ro</h3><span><span class="pill ${o.risk.score >= 50 ? "bad" : o.risk.score >= 30 ? "warn" : "ok"}">${o.risk.score}/100</span> ${o.risk.needVerify ? (o.risk.verified ? '<span class="pill ok">Đã xác minh</span>' : '<span class="pill bad">Cần xác minh</span>') : ""}</span>${o.risk.reasons.length ? `<ul class="small" style="margin:0;padding-left:18px">${o.risk.reasons.map((r) => `<li>${esc(r)}</li>`).join("")}</ul>` : ""}
      <h3>Thao tác</h3><div class="stack" style="gap:8px">${act.join("") || '<span class="small muted">Không còn thao tác.</span>'}<button class="btn sm plain" type="button" id="pr">In phiếu</button></div></div></div>`;
  }, (id) => {
    const o = E.findOrder(id) || S.orders.find((x) => x.status === "Mới") || S.orders[0];
    const on = (s, f) => { const b = $(s); if (b) b.onclick = f; };
    on("#vf", () => { o.risk.verified = true; E.olog(o, "Gọi điện xác minh đơn rủi ro: khách xác nhận"); rerender(); });
    on("#cf", () => { const err = E.confirmOrder(o); toast(err || "Đã xác nhận: " + o.status); rerender(); });
    on("#nx", () => { E.toNext(o); rerender(); });
    on("#rc", () => { const s = E.recheck(o); toast(s.length ? "Vẫn thiếu hàng" : "Đã đủ hàng"); rerender(); });
    on("#cx", () => { if (!confirm("Hủy đơn " + o.id + "?")) return; toast(E.cancel(o) || "Đã hủy, giải phóng hàng"); rerender(); });
    on("#pr", () => { E.olog(o, "In phiếu xuất/đơn hàng"); toast("Đã gửi phiếu tới máy in (demo)"); rerender(); });
  });

  // ================= SC27 – Bảng điều phối xưởng =================
  add("SC27", "workshop", "Bảng điều phối xưởng", "UC15", "admin", () => {
    const cols = ["Chờ hàng", "Lắp ráp & QC", "Đóng gói", "Đang giao / Chờ nhận"];
    return `${head("Điều phối xưởng", "Công suất tham chiếu: 1 kỹ thuật viên ≈ 3 bộ/ngày (lắp + burn-in 2–4 giờ).", "SC27", "UC15")}
    <div class="board" style="margin-top:12px;grid-template-columns:repeat(4,minmax(200px,1fr))">${cols.map((st) => { const its = S.orders.filter((o) => o.status === st && (o.asm || st !== "Chờ hàng")); return `<div class="col"><h3><span>${st}</span><span>${its.length}</span></h3>${its.map((o) => `<div class="tk"><a class="id" href="#/${st === "Lắp ráp & QC" ? "ticket" : "order"}/${o.id}">${o.id}</a><br><b>${esc(o.lines.map(lineTitle).join(", "))}</b><br><span class="xs muted">${esc(o.cust.name)}${o.asm ? " · lắp ráp" : " · không lắp"}</span>${st === "Lắp ráp & QC" ? `<select data-tech="${o.id}" style="margin-top:6px" aria-label="Kỹ thuật viên"><option value="">Chưa phân công</option>${[...new Set(TECHS())].map((t) => `<option ${o.tech === t ? "selected" : ""}>${t}</option>`).join("")}</select>` : ""}${st === "Chờ hàng" ? `<br><span class="pill warn">Thiếu ${o.short.map((s) => s.id).join(", ")}</span>` : ""}</div>`).join("")}</div>`; }).join("")}</div>`;
  }, () => { $$("[data-tech]").forEach((s) => (s.onchange = () => { const o = E.findOrder(s.dataset.tech); o.tech = s.value; E.olog(o, "Phân công kỹ thuật viên: " + s.value); toast("Đã phân công"); })); });

  // ================= SC28 – Phiếu lắp ráp & QC =================
  const CHECK = ["Đối chiếu serial đã giữ với phiếu", "Lắp CPU, tra keo, lắp tản", "Lắp RAM đúng kênh, SSD vào khe M.2", "Đi dây nguồn sau khay, buộc gọn", "Lắp VGA, cắm đủ đầu nguồn", "Cập nhật BIOS và driver", "Chụp ảnh đi dây"];
  S.tk = S.tk || {};
  add("SC28", "ticket", "Phiếu lắp ráp & QC", "UC15", "admin", (id) => {
    const o = E.findOrder(id) || S.orders.find((x) => x.status === "Lắp ráp & QC");
    if (!o) return `${head("Phiếu lắp ráp & QC", "", "SC28", "UC15")}<div class="empty">Không có đơn nào đang ở bước Lắp ráp & QC.</div>`;
    const t = S.tk[o.id] || (S.tk[o.id] = { chk: [], ser: false, photos: 0 }), held = E.units.filter((u) => u.order === o.id);
    return `<a href="#/workshop" class="small">← Điều phối xưởng</a>${head("Phiếu lắp ráp " + o.id, `${esc(o.lines.map(lineTitle).join(", "))} · KTV ${esc(o.tech || "chưa phân công")} · Ngưỡng đạt: CPU &lt; 90°C, GPU &lt; 85°C, 0 lỗi RAM, burn-in ≥ 120 phút.`, "SC28", "UC15")}
    ${o.status !== "Lắp ráp & QC" ? `<div class="notice">Đơn đang ở trạng thái ${o.status}.</div>` : ""}
    <div class="grid2" style="margin-top:12px"><div class="stack"><div class="panel"><h3>Checklist lắp ráp</h3>${CHECK.map((c, i) => `<label class="row small"><input type="checkbox" data-c="${i}" ${t.chk.includes(i) ? "checked" : ""}> ${c}</label>`).join("")}</div>
      <div class="panel"><h3>Serial đã giữ</h3><div class="tbl"><table><tbody>${held.map((u) => `<tr><td class="small">${CAT[byId(u.id).cat]}</td><td class="small">${esc(byId(u.id).n)}</td><td class="mono xs">${u.sn}</td></tr>`).join("")}</tbody></table></div><label class="row small" style="margin-top:8px"><input type="checkbox" id="ser" ${t.ser ? "checked" : ""}> Đã quét và khớp ${held.length} serial</label><div class="field" style="margin-top:8px"><label for="ph">Ảnh đi dây (${t.photos})</label><input id="ph" type="file" accept="image/*" multiple></div></div></div>
    <form class="panel" id="qc"><h3>Kết quả burn-in</h3><p class="xs muted">MemTest86, FurMark, Cinebench R23 trong 2–4 giờ.</p><div class="grid2">
      <div class="field"><label for="q1">CPU tối đa (°C)</label><input id="q1" type="number" value="72" required></div><div class="field"><label for="q2">GPU tối đa (°C)</label><input id="q2" type="number" value="69" required></div>
      <div class="field"><label for="q3">Lỗi MemTest86</label><input id="q3" type="number" value="0" required></div><div class="field"><label for="q4">Cinebench R23</label><input id="q4" type="number" value="12100" required></div>
      <div class="field"><label for="q5">Thời gian burn-in (phút)</label><input id="q5" type="number" value="180" required></div><div class="field"><label for="q6">Ghi chú</label><input id="q6" type="text"></div></div>
      <button class="btn" type="submit" ${o.status === "Lắp ráp & QC" ? "" : "disabled"}>Ghi kết quả QC</button><div id="qr" style="margin-top:10px"></div></form></div>`;
  }, (id) => {
    const o = E.findOrder(id) || S.orders.find((x) => x.status === "Lắp ráp & QC"); if (!o) return;
    const t = S.tk[o.id];
    $$("[data-c]").forEach((c) => (c.onchange = () => { const i = +c.dataset.c; t.chk = c.checked ? [...t.chk, i] : t.chk.filter((x) => x !== i); }));
    $("#ser").onchange = (e) => (t.ser = e.target.checked);
    $("#ph").onchange = (e) => { t.photos += e.target.files.length; toast(`Đã tải ${e.target.files.length} ảnh`); };
    $("#qc").onsubmit = (e) => {
      e.preventDefault();
      if (t.chk.length < CHECK.length || !t.ser) return toast("Hoàn thành checklist và đối chiếu serial trước khi ghi QC");
      const r = { cpu: +$("#q1").value, gpu: +$("#q2").value, ram: +$("#q3").value, cb: +$("#q4").value, min: +$("#q5").value, photos: t.photos || 4, note: $("#q6").value };
      r.pass = r.cpu < 90 && r.gpu < 85 && r.ram === 0 && r.min >= 120;
      E.qcResult(o, r);
      toast(r.pass ? "QC đạt → Đóng gói" : "QC không đạt → đã mở RMA");
      if (r.pass) go("#/packing"); else go("#/rma");
    };
  });

  // ================= SC29 – Đóng gói & bàn giao =================
  add("SC29", "packing", "Đóng gói & bàn giao", "UC15", "admin", () => {
    const pk = S.orders.filter((o) => o.status === "Đóng gói"), sh = S.orders.filter((o) => o.status === "Đang giao / Chờ nhận");
    return `${head("Đóng gói & bàn giao", "Xuất kho ghi một lần khi bàn giao cho vận chuyển hoặc cho khách.", "SC29", "UC15")}
    <div class="grid2" style="margin-top:12px"><div class="panel"><h3>Checklist đóng gói PC</h3>${["Bơm bọt khí nở cố định VGA và tản nhiệt", "Thùng 5 lớp, dán tem “Hàng dễ vỡ”", "Liên tỉnh: đóng kiện gỗ, khai giá trị", "Chụp ảnh trước khi đóng thùng", "Kèm phiếu bảo hành và báo cáo burn-in"].map((x) => `<label class="row small"><input type="checkbox" checked> ${x}</label>`).join("")}</div>
    <div class="panel"><h3>Chờ đóng gói (${pk.length})</h3><div class="stack" style="gap:8px">${pk.map((o) => `<div class="row between small"><span><a class="mono" href="#/order/${o.id}">${o.id}</a> · ${esc(o.cust.name)}<br><span class="xs muted">${o.ship.mode === "in" ? "Giao nội thành – Ahamove" : o.ship.mode === "out" ? "Liên tỉnh – GHN, kiện gỗ" : "Khách nhận tại cửa hàng"}</span></span><button class="btn sm" type="button" data-ship="${o.id}">${o.ship.mode === "pickup" ? "Hẹn khách nhận" : "Tạo vận đơn & xuất kho"}</button></div>`).join("") || '<p class="small muted">Không có.</p>'}</div></div></div>
    <div class="panel" style="margin-top:16px"><h3>Đang giao / chờ nhận (${sh.length})</h3><div class="tbl"><table><thead><tr><th>Đơn</th><th>Khách</th><th>Vận đơn</th><th>Thanh toán</th><th></th></tr></thead><tbody>${sh.map((o) => `<tr><td class="mono"><a href="#/order/${o.id}">${o.id}</a></td><td>${esc(o.cust.name)}</td><td class="mono small">${esc(o.waybill)}</td><td>${payPill(o.pay)} <span class="xs muted">còn ${fmt(o.total - o.pay.paid)}</span></td><td><button class="btn sm" type="button" data-done="${o.id}">Đã giao${o.total > o.pay.paid ? " & thu đủ" : ""}</button></td></tr>`).join("") || '<tr><td colspan="5" class="muted">Không có.</td></tr>'}</tbody></table></div><p class="xs muted" style="margin-top:6px">${tag("SC29", "UC15")}</p></div>`;
  }, () => {
    $$("[data-ship]").forEach((b) => (b.onclick = () => { const o = E.findOrder(b.dataset.ship); const wb = o.ship.mode === "pickup" ? "Chờ khách nhận tại cửa hàng" : o.ship.mode === "out" ? "GHN " + Math.random().toString(36).slice(2, 7).toUpperCase() : "AHM-" + (77311 + S.orders.indexOf(o)); toast(E.ship(o, wb) || "Đã xuất kho: " + wb); rerender(); }));
    $$("[data-done]").forEach((b) => (b.onclick = () => { toast(E.complete(E.findOrder(b.dataset.done)) || "Hoàn tất, kích hoạt bảo hành"); rerender(); }));
  });

  // ================= SC30 – Tồn kho theo serial =================
  const MIN = { ram: 6, ssd: 5, psu: 4, case: 3, cool: 4, opt: 3, cpu: 2, main: 2, vga: 2 };
  add("SC30", "stock", "Tồn kho theo serial", "UC16", "admin", () => {
    const rows = E.P.filter((p) => !p.ref).map((p) => { const oh = E.onHand(p.id), h = E.held(p.id), a = E.avail(p.id), aged = E.units.filter((u) => u.id === p.id && u.state === "stock" && E.days(u.inDate) > 60).length, min = p.grp === "C" ? 0 : MIN[p.cat]; return { p, oh, h, a, aged, min, low: p.grp !== "C" && a < min }; });
    const value = E.units.filter((u) => u.state !== "out").reduce((t, u) => t + byId(u.id).cost, 0);
    return `${head("Tồn kho", `Khả dụng = thực tế − đã giữ. Giá trị tồn ${fmt(value)} (mục tiêu ~nửa tháng giá vốn). Nhóm C nhập theo đơn.`, "SC30", "UC16")}
    <div class="grid4" style="margin-top:12px"><div class="kpi"><div class="lbl">Mã sắp hết</div><div class="v">${rows.filter((r) => r.low).length}</div></div><div class="kpi"><div class="lbl">Serial tồn &gt; 60 ngày</div><div class="v">${rows.reduce((t, r) => t + r.aged, 0)}</div></div><div class="kpi"><div class="lbl">Đang giữ cho đơn</div><div class="v">${rows.reduce((t, r) => t + r.h, 0)}</div></div><div class="kpi"><div class="lbl">Tổng serial trong kho</div><div class="v">${rows.reduce((t, r) => t + r.oh, 0)}</div></div></div>
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Linh kiện</th><th>Nhóm</th><th class="num">Thực tế</th><th class="num">Đã giữ</th><th class="num">Khả dụng</th><th class="num">Tối thiểu</th><th>Cảnh báo</th><th>Serial</th></tr></thead><tbody>${rows.map((r) => `<tr><td class="mono">${r.p.id}</td><td class="small">${esc(r.p.n)}</td><td>${r.p.grp}</td><td class="num">${r.oh}</td><td class="num">${r.h}</td><td class="num">${r.a}</td><td class="num">${r.min || "–"}</td><td>${r.low ? '<span class="pill warn">Sắp hết</span> ' : ""}${r.aged ? `<span class="pill bad">${r.aged} tồn &gt; 60 ngày</span>` : ""}${r.p.grp === "C" ? '<span class="pill">Nhập theo đơn</span>' : ""}</td><td><details><summary class="xs">Xem</summary><div class="xs mono">${E.units.filter((u) => u.id === r.p.id && u.state !== "out").map((u) => `${u.sn} · ${u.state === "held" ? "giữ " + u.order : "trong kho"} · nhập ${E.dstr(u.inDate)}`).join("<br>") || "—"}</div></details></td></tr>`).join("")}</tbody></table></div>`;
  });

  // ================= SC31 – Phiếu nhập/xuất/điều chỉnh =================
  add("SC31", "stockdoc", "Phiếu nhập/xuất/điều chỉnh", "UC16", "admin", () => {
    const opts = E.P.filter((p) => !p.ref).map((p) => `<option value="${p.id}">${p.id} · ${esc(p.n)}</option>`).join("");
    const kl = S.log.filter((l) => /kho|Nhận hàng|Nhập/.test(l.action)).slice(0, 8);
    return `${head("Phiếu kho", "Mọi điều chỉnh phải có lý do và được lưu vết. Hàng khách trả chỉ nhập lại sau khi kiểm tra.", "SC31", "UC16")}
    <div class="grid3" style="margin-top:12px"><form class="panel" id="fin"><h3>Nhập kho theo serial</h3><div class="field"><label for="ip">Sản phẩm</label><select id="ip">${opts}</select></div><div class="field"><label for="iq">Số lượng</label><input id="iq" type="number" min="1" value="2"></div><div class="field"><label for="is">Hóa đơn NPP</label><input id="is" type="text" value="HĐ 0001523" required></div><button class="btn sm" type="submit">Quét & nhập</button></form>
    <form class="panel" id="fad"><h3>Xuất / điều chỉnh</h3><div class="field"><label for="ap">Sản phẩm</label><select id="ap">${opts}</select></div><div class="field"><label for="aq">Số lượng (+ tăng, − giảm)</label><input id="aq" type="number" value="-1"></div><div class="field"><label for="ar">Lý do (bắt buộc)</label><select id="ar"><option value="">— chọn —</option><option>Kiểm kê lệch</option><option>Hàng trưng bày / demo</option><option>Hàng lỗi gửi NPP</option><option>Xuất dùng nội bộ</option></select></div><button class="btn sm" type="submit">Ghi phiếu</button></form>
    <form class="panel" id="frt"><h3>Nhận hàng khách trả</h3><div class="field"><label for="rs">Serial</label><input id="rs" type="text" placeholder="VD: R01-10xx" required></div><div class="field"><label for="rk">Kết quả kiểm tra</label><select id="rk"><option value="ok">Đạt – nhập lại kho</option><option value="bad">Lỗi – chuyển RMA</option></select></div><button class="btn sm" type="submit">Ghi nhận</button><p class="xs muted">Serial đã xuất gần nhất: ${E.units.filter((u) => u.state === "out").slice(-3).map((u) => u.sn).join(", ")}</p></form></div>
    <div class="panel" style="margin-top:16px"><h3>Nhật ký kho gần đây</h3>${kl.map((l) => `<div class="small"><span class="mono xs muted">${E.tstr(l.t)}</span> · ${esc(l.who)}: ${esc(l.action)} <span class="mono xs">${esc(l.target)}</span></div>`).join("") || '<p class="small muted">Chưa có.</p>'}</div>`;
  }, () => {
    $("#fin").onsubmit = (e) => { e.preventDefault(); const id = $("#ip").value, q = Math.max(1, +$("#iq").value); E.receive(id, q, E.TODAY, $("#is").value); E.log(`Nhập kho ${q} serial theo ${$("#is").value}`, id); S.orders.filter((o) => o.status === "Chờ hàng").forEach(E.recheck); toast("Đã nhập " + q + " serial"); rerender(); };
    $("#fad").onsubmit = (e) => { e.preventDefault(); const id = $("#ap").value, q = +$("#aq").value, r = $("#ar").value; if (!r) return toast("Phải chọn lý do"); if (q > 0) E.receive(id, q); else { const us = E.units.filter((u) => u.id === id && u.state === "stock").slice(0, -q); if (us.length < -q) return toast("Không đủ hàng khả dụng"); us.forEach((u) => { u.state = "out"; u.order = "ĐIỀU CHỈNH"; }); } E.log(`Điều chỉnh kho ${q > 0 ? "+" : ""}${q} (${r})`, id); toast("Đã ghi phiếu, lưu vết"); rerender(); };
    $("#frt").onsubmit = (e) => { e.preventDefault(); const sn = $("#rs").value.trim(), u = E.units.find((x) => x.sn === sn); if (!u || u.state !== "out") return toast("Không tìm thấy serial đã xuất"); if ($("#rk").value === "ok") { u.state = "stock"; u.order = null; E.log("Nhập lại hàng khách trả sau kiểm tra", sn); } else { S.rma.unshift({ id: "RMA-" + (302 + S.rma.length), sn, order: u.order, symptom: "Hàng khách trả bị lỗi", diag: "", action: "Gửi NPP", st: "Đang xử lý", hist: ["Tiếp nhận hàng trả"] }); E.log("Hàng trả lỗi → RMA", sn); } toast("Đã ghi nhận"); rerender(); };
  });

  // ================= SC32 – Nhà cung cấp & bảng giá nhập =================
  add("SC32", "suppliers", "Nhà cung cấp & bảng giá nhập", "UC17", "admin", () => `${head("Nhà cung cấp", "Chỉ nhập hàng có hóa đơn và bảo hành chính hãng; 2–3 NPP và 1 nguồn dự phòng. Tên NPP và chiết khấu là giả định, cần báo giá thật.", "SC32", "UC17")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Tên</th><th>Nhóm hàng</th><th>Chiết khấu</th><th>Công nợ</th><th>Giao hàng</th><th>Đổi trả (RMA)</th><th>Trạng thái</th></tr></thead><tbody>${S.suppliers.map((s, i) => `<tr><td class="mono">${s.id}</td><td>${esc(s.name)}</td><td class="small">${esc(s.grp)}</td><td>${s.disc}</td><td class="small">${esc(s.debt)}</td><td class="small">${s.lead}</td><td class="small">${esc(s.rma)}</td><td><button class="btn sm plain" type="button" data-t="${i}">${s.active ? "Đang dùng" : "Dự phòng"}</button></td></tr>`).join("")}</tbody></table></div>
    <h2 style="margin-top:22px">Bảng giá nhập (20/10/2026)</h2><div class="tbl"><table><thead><tr><th>Mã</th><th>Linh kiện</th><th>NPP</th><th class="num">Giá thị trường</th><th class="num">CK NPP</th><th class="num">Giá vốn</th><th class="num">Giá bán (+8%)</th><th class="num">Biên gộp</th></tr></thead><tbody>${E.P.filter((p) => !p.ref).map((p) => `<tr><td class="mono">${p.id}</td><td class="small">${esc(p.n)}${p.demo ? ' <span class="pill">minh họa</span>' : ""}</td><td class="mono xs">${E.supplierFor(p.id)}</td><td class="num">${fmt(p.mkt)}</td><td class="num">${Math.round(p.disc * 100)}%</td><td class="num">${fmt(p.cost)}</td><td class="num">${fmt(p.price)}</td><td class="num">${((1 - p.cost / p.price) * 100).toLocaleString("vi-VN", { maximumFractionDigits: 1 })}%</td></tr>`).join("")}</tbody></table></div>`,
  () => { $$("[data-t]").forEach((b) => (b.onclick = () => { const s = S.suppliers[+b.dataset.t]; s.active = !s.active; E.log("Đổi trạng thái NPP", s.id); rerender(); })); });

  // ================= SC33 – Đơn nhập hàng =================
  add("SC33", "po", "Đơn nhập hàng", "UC17", "admin", () => {
    const sug = E.poSuggestions();
    return `${head("Đơn nhập hàng", "Hệ thống gợi ý từ đơn thiếu hàng (nhóm C đặt theo đơn khách); quản lý duyệt rồi gửi NPP.", "SC33", "UC17")}
    <div class="panel" style="margin-top:12px"><h3>Gợi ý từ đơn thiếu hàng (${sug.length})</h3>${sug.length ? `<div class="tbl"><table><thead><tr><th>Đơn khách</th><th>Linh kiện</th><th class="num">SL</th><th>NPP</th><th></th></tr></thead><tbody>${sug.map((s, i) => `<tr><td class="mono"><a href="#/order/${s.order}">${s.order}</a></td><td>${esc(byId(s.id).n)}</td><td class="num">${s.q}</td><td class="mono xs">${s.sup}</td><td><button class="btn sm" type="button" data-sug="${i}">Tạo đơn nhập</button></td></tr>`).join("")}</tbody></table></div>` : '<p class="small muted">Không có đơn thiếu hàng chưa đặt.</p>'}</div>
    <div class="tbl" style="margin-top:16px"><table><thead><tr><th>Đơn nhập</th><th>NPP</th><th>Hàng</th><th>Cho đơn</th><th>Dự kiến về</th><th>Trạng thái</th><th></th></tr></thead><tbody>${E.POS.map((p, i) => `<tr><td class="mono">${p.id}</td><td class="mono xs">${p.sup}</td><td class="small">${p.items.map((x) => esc(byId(x.id).n) + " ×" + x.q).join(", ")}</td><td class="mono xs">${p.forOrder}</td><td>${p.eta || "—"}</td><td><span class="pill ${p.status === "Đã nhận" ? "ok" : "info"}">${p.status}</span></td><td>${p.status === "Chờ duyệt" ? `<button class="btn sm" type="button" data-ap="${i}">Duyệt & gửi NPP</button>` : p.status === "Đã gửi NPP" ? `<button class="btn sm plain" type="button" data-cf="${i}">NPP xác nhận</button>` : p.status === "NPP xác nhận" ? `<button class="btn sm" type="button" data-rc="${i}">Nhận hàng</button>` : ""}</td></tr>`).join("")}</tbody></table></div>`;
  }, () => {
    const sug = E.poSuggestions();
    $$("[data-sug]").forEach((b) => (b.onclick = () => { const s = sug[+b.dataset.sug]; const same = sug.filter((x) => x.order === s.order && x.sup === s.sup); E.createPO(same.map((x) => ({ id: x.id, q: x.q })), s.sup, s.order); rerender(); }));
    $$("[data-ap]").forEach((b) => (b.onclick = () => { if (S.staff.role !== "Quản lý") return toast("Chỉ quản lý được duyệt đơn nhập"); const p = E.POS[+b.dataset.ap]; p.status = "Đã gửi NPP"; E.log("Duyệt và gửi đơn nhập", p.id); rerender(); }));
    $$("[data-cf]").forEach((b) => (b.onclick = () => { const p = E.POS[+b.dataset.cf]; p.status = "NPP xác nhận"; p.eta = "18/04/2027"; const o = E.findOrder(p.forOrder); if (o) E.olog(o, "NPP xác nhận, dự kiến về 18/04"); rerender(); }));
    $$("[data-rc]").forEach((b) => (b.onclick = () => { const p = E.POS[+b.dataset.rc]; E.receivePO(p); toast("Đã nhập kho theo serial; đơn chờ hàng được kiểm tra lại"); rerender(); }));
  });

  // ================= SC34 – Danh mục sản phẩm & giá =================
  const REQF = { cpu: ["socket", "w", "igpu", "box"], main: ["socket", "ram", "slots", "maxRam", "ff", "m2", "sata", "x1"], ram: ["type", "gb", "bus"], vga: ["w", "len", "pin8"], ssd: ["iface", "form"], cool: ["sockets", "h", "tdp"], case: ["ff", "gpu", "cool", "rad"], psu: ["w", "pin8"], opt: [] };
  S.drafts = S.drafts || [];
  add("SC34", "products", "Danh mục sản phẩm & giá", "UC18", "admin", () => `${head("Sản phẩm & giá bán", "Giá bán = giá lẻ thấp nhất × 1,08, làm tròn 10.000đ. Đổi giá được lưu vết. Sản phẩm thiếu trường tương thích không được xuất bản.", "SC34", "UC18")}
    <div class="grid2" style="margin-top:12px"><form class="panel" id="fp"><h3>Thêm sản phẩm</h3><div class="grid2"><div class="field"><label for="pc">Loại</label><select id="pc">${Object.entries(CAT).map(([k, v]) => `<option value="${k}">${v}</option>`).join("")}</select></div><div class="field"><label for="pm">Giá thị trường</label><input id="pm" type="number" value="2990000" required></div></div><div class="field"><label for="pn">Tên</label><input id="pn" type="text" value="RAM DDR4 32GB 3200" required></div><div class="field"><label for="pf">Thông số tương thích (khóa=giá trị, mỗi dòng một trường)</label><textarea id="pf">type=DDR4\ngb=32</textarea></div><p class="xs muted" id="rq"></p><button class="btn sm" type="submit">Lưu</button></form>
    <form class="panel" id="fv"><h3>Nhập CSV</h3><div class="field"><label for="cv">Mỗi dòng: loại;tên;giá;khóa=giá trị|…</label><textarea id="cv">ssd;SSD NVMe Gen4 2TB;7990000;iface=NVMe|form=M.2|gb=2000\nvga;GeForce RTX 5060 8GB OC;10990000;w=145|len=245</textarea></div><button class="btn sm" type="submit">Kiểm tra & nhập</button><div id="cvr" style="margin-top:8px"></div></form></div>
    ${S.drafts.length ? `<div class="panel" style="margin-top:16px"><h3>Nháp chưa xuất bản</h3>${S.drafts.map((d, i) => `<div class="row between small"><span>${esc(d.n)} · ${CAT[d.cat]} ${d.miss.length ? `<span class="pill bad">Thiếu: ${d.miss.join(", ")}</span>` : '<span class="pill ok">Đủ trường</span>'}</span><button class="btn sm" type="button" data-pub="${i}" ${d.miss.length ? "disabled" : ""}>Xuất bản</button></div>`).join("")}</div>` : ""}
    <div class="tbl" style="margin-top:16px"><table><thead><tr><th>Mã</th><th>Sản phẩm</th><th class="num">Giá thị trường</th><th>Giá bán</th><th>Tồn khả dụng</th></tr></thead><tbody>${E.P.filter((p) => !p.ref).map((p) => `<tr><td class="mono">${p.id}</td><td class="small">${esc(p.n)}</td><td class="num">${fmt(p.mkt)}</td><td><div class="row" style="flex-wrap:nowrap"><input type="number" step="10000" value="${p.price}" data-pr="${p.id}" style="width:140px" aria-label="Giá bán ${p.id}"></div></td><td>${availPill(p)}</td></tr>`).join("")}</tbody></table></div>`,
  () => {
    const parse = (txt, sep) => Object.fromEntries(txt.split(sep).map((l) => l.split("=").map((x) => x.trim())).filter((x) => x[0]));
    const showReq = () => ($("#rq").textContent = "Trường bắt buộc cho " + CAT[$("#pc").value] + ": " + (REQF[$("#pc").value].join(", ") || "không"));
    $("#pc").onchange = showReq; showReq();
    const draft = (cat, n, mkt, f) => { const miss = REQF[cat].filter((k) => !(k in f)); S.drafts.push({ cat, n, mkt, f, miss }); return miss; };
    $("#fp").onsubmit = (e) => { e.preventDefault(); const miss = draft($("#pc").value, $("#pn").value, +$("#pm").value, parse($("#pf").value, "\n")); toast(miss.length ? "Lưu nháp – thiếu " + miss.join(", ") : "Đủ trường, có thể xuất bản"); rerender(); };
    $("#fv").onsubmit = (e) => { e.preventDefault(); let ok = 0, bad = 0; $("#cv").value.split("\n").filter(Boolean).forEach((l) => { const [cat, n, mkt, f] = l.split(";"); if (!CAT[cat]) { bad++; return; } const m = draft(cat, n, +mkt, parse(f || "", "|")); m.length ? bad++ : ok++; }); toast(`${ok} dòng đủ trường, ${bad} dòng thiếu trường (lưu nháp)`); rerender(); };
    $$("[data-pub]").forEach((b) => (b.onclick = () => { const d = S.drafts.splice(+b.dataset.pub, 1)[0]; const id = d.cat.slice(0, 1).toUpperCase() + "N" + (E.P.length + 1); const num = (v) => (isNaN(+v) ? (v === "true" ? true : v === "false" ? false : v) : +v); const f = Object.fromEntries(Object.entries(d.f).map(([k, v]) => [k, k === "ff" && d.cat === "case" ? v.split(",") : k === "sockets" ? v.split(",") : num(v)])); const p = Object.assign({ id, cat: d.cat, n: d.n, brand: "Mới", mkt: d.mkt, disc: 0.07, grp: "A", stock: 0, why: "Sản phẩm mới nhập.", spec: {} }, f); p.price = window.BX.sell(p.mkt); p.cost = Math.round(p.mkt * 0.93); E.P.push(p); E.log("Xuất bản sản phẩm mới", id); rerender(); }));
    $$("[data-pr]").forEach((i) => (i.onchange = () => { const p = byId(i.dataset.pr), old = p.price; p.price = Math.round(+i.value / 10000) * 10000; E.log(`Đổi giá bán ${p.id}: ${fmt(old)} → ${fmt(p.price)}`, p.id); toast("Đã đổi giá, lưu vết"); }));
  });

  // ================= SC35 – Thông số & luật tương thích =================
  const mk = (o) => { const c = E.emptyCfg(); Object.entries(o).forEach(([k, v]) => { if (k === "extras") c.extras = v.map((id) => ({ id, qty: 1 })); else { const [id, q] = String(v).split("x"); c[k] = { mode: "buy", id, qty: +(q || 1) }; } }); return c; };
  const TESTS = [
    ["R1", "ok", "i5-12400F + H610M (LGA1700)", { cpu: "C01", main: "M01" }], ["R1", "bad", "Ryzen 7500F (AM5) + H610M (LGA1700)", { cpu: "C04", main: "M01" }],
    ["R2", "ok", "H610M + 2 thanh DDR4 16GB", { main: "M01", ram: "R01x2" }], ["R2", "bad", "H610M (DDR4) + RAM DDR5", { main: "M01", ram: "R02" }], ["R2", "bad", "H610M 2 khe + 3 thanh RAM", { main: "M01", ram: "R01x3" }], ["R2", "warn", "H610M + RAM bus 3600", { main: "M01", ram: "R04" }],
    ["R3", "ok", "B760M (mATX) + case mATX", { main: "M02", case: "K01" }], ["R3", "bad", "B760 ATX + case chỉ nhận mATX", { main: "M06", case: "K01" }],
    ["R4", "ok", "RTX 5060 (240 mm) + case 300 mm", { vga: "G02", case: "K01" }], ["R4", "bad", "RTX 5070 Ti (330 mm) + case 300 mm", { vga: "G05", case: "K01" }],
    ["R5", "ok", "Hyper 212 + i5-12400F + case 155 mm", { cpu: "C01", cool: "T01", case: "K01" }], ["R5", "bad", "Tản chỉ ngàm LGA1700 + Ryzen AM5", { cpu: "C04", cool: "T03" }], ["R5", "bad", "Tản 157 mm + case 155 mm", { cool: "T02", case: "K01" }], ["R5", "bad", "AIO 240 + case không có chỗ radiator", { cool: "T04", case: "K03" }], ["R5", "warn", "i5-14600KF 181W + tản 150W", { cpu: "C02", cool: "T01" }],
    ["R6", "ok", "i5-12400F + RTX 5060 + 650W", { cpu: "C01", vga: "G02", psu: "P01" }], ["R6", "warn", "i5-14600KF + RTX 5070 + 650W (dư tải < 30%)", { cpu: "C02", vga: "G04", psu: "P01" }], ["R6", "bad", "RTX 5070 Ti cần 3 đầu 8-pin + nguồn 2 đầu", { cpu: "C01", vga: "G05", psu: "P01" }], ["R6", "bad", "i5-14600KF + RTX 5070 Ti + 550W (dưới tải)", { cpu: "C02", vga: "G05", psu: "P03" }],
    ["R7", "ok", "B760M 2 khe M.2 + 2 SSD NVMe", { main: "M02", ssd: "S01", extras: ["S02"] }], ["R7", "bad", "H610M 1 khe M.2 + 2 SSD NVMe", { main: "M01", ssd: "S01", extras: ["S02"] }],
    ["R8", "ok", "B760M có PCIe x1 + card WiFi", { main: "M02", extras: ["W01"] }], ["R8", "bad", "Mini-ITX không có PCIe x1 + card WiFi", { main: "M05", extras: ["W01"] }], ["R8", "bad", "Case Mini-ITX còn 1 vị trí + bộ 3 quạt", { case: "K03", extras: ["F01"] }],
  ];
  const runTest = ([r, exp, , o]) => { const rs = E.evalRules(mk(o)).filter((x) => x.r === r); const got = rs.length ? E.worst(rs) : "—"; return { got, pass: got === exp, msg: (rs.find((x) => x.lv === got) || {}).m || "" }; };
  add("SC35", "rules", "Thông số & luật tương thích", "UC18", "admin", () => {
    const res = TESTS.map(runTest), pass = res.filter((x) => x.pass).length;
    return `${head("Luật tương thích", "Luật lưu dạng dữ liệu: engine đọc trường tương thích của từng sản phẩm, nên thêm sản phẩm mới không phải sửa code. Website, POS và báo giá dùng chung một bộ luật.", "SC35", "UC18")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Luật</th><th>Điều kiện</th><th>Mức xử lý</th><th>Dữ liệu cần có</th><th class="num">Ca kiểm thử</th></tr></thead><tbody>${E.RULES.map((r) => `<tr><td class="mono">${r.id}</td><td><b>${r.name}</b></td><td class="small">${r.cond}</td><td class="small">${r.lv}</td><td class="small">${r.data}</td><td class="num">${TESTS.filter((t) => t[0] === r.id).length}</td></tr>`).join("")}</tbody></table></div>
    <div class="row between" style="margin-top:18px"><h2 style="margin:0">Bộ cấu hình kiểm thử: ${pass}/${TESTS.length} đạt</h2><button class="btn sm" type="button" id="rr">Chạy lại</button></div><p class="small muted">Mỗi luật có ít nhất một cấu hình đúng và một cấu hình sai; chạy lại sau mỗi lần sửa luật.</p>
    <div class="tbl"><table><thead><tr><th>Luật</th><th>Cấu hình</th><th>Kỳ vọng</th><th>Kết quả</th><th>Thông báo của engine</th><th></th></tr></thead><tbody>${TESTS.map((t, i) => `<tr><td class="mono">${t[0]}</td><td class="small">${esc(t[2])}</td><td><span class="pill ${t[1] === "ok" ? "ok" : t[1] === "warn" ? "warn" : "bad"}">${t[1] === "ok" ? "Đạt" : t[1] === "warn" ? "Cảnh báo" : "Chặn"}</span></td><td><span class="pill ${res[i].got === "ok" ? "ok" : res[i].got === "warn" ? "warn" : "bad"}">${res[i].got === "ok" ? "Đạt" : res[i].got === "warn" ? "Cảnh báo" : res[i].got === "bad" ? "Chặn" : "—"}</span></td><td class="small">${esc(res[i].msg)}</td><td>${res[i].pass ? '<span class="pill ok">PASS</span>' : '<span class="pill bad">FAIL</span>'}</td></tr>`).join("")}</tbody></table></div>`;
  }, () => { $("#rr").onclick = () => { rerender(); toast("Đã chạy lại " + TESTS.length + " ca kiểm thử"); }; });

  // ================= SC36 – Combo & linh kiện tùy chọn =================
  const OPT_POOL = ["R01", "R03", "S01", "S02", "S03", "F01", "W01", "D01", "KB1"];
  add("SC36", "combos", "Combo & linh kiện tùy chọn", "UC18", "admin", () => `${head("Combo & linh kiện tùy chọn", "Đổi linh kiện chính (chỉ liệt kê loại tương thích), khai báo danh sách linh kiện tùy chọn; combo chỉ xuất bản khi qua toàn bộ luật.", "SC36", "UC18")}
    <div class="grid2" style="margin-top:12px">${COMBOS.map((cb) => { const c = E.cfgFromCombo(cb.key), rs = E.evalRules(c), price = E.cfgPrice(c), cost = E.cfgCost(c); return `<div class="panel"><div class="row between"><h3 style="margin:0">${cb.name}</h3><span class="pill ${E.worst(rs) === "bad" ? "bad" : "ok"}">${E.worst(rs) === "bad" ? "Lỗi – không xuất bản" : "Đã xuất bản"}</span></div><p class="small muted">${fmt(price)} · biên gộp ${((1 - cost / price) * 100).toLocaleString("vi-VN", { maximumFractionDigits: 1 })}% · tỷ trọng ${cb.share}%</p>
      ${ORDER.map((s) => { const opts = sellable(s).filter((p) => p.id === cb.parts[s] || !E.tryPart(c, s, p.id).bad.length); return `<div class="row small" style="flex-wrap:nowrap;margin-bottom:4px"><span style="width:84px">${CAT[s]}</span><select data-cb="${cb.key}" data-s="${s}" aria-label="${CAT[s]} ${cb.name}">${opts.map((p) => `<option value="${p.id}" ${p.id === cb.parts[s] ? "selected" : ""}>${esc(p.n)}</option>`).join("")}</select></div>`; }).join("")}
      <h3 style="margin-top:10px">Linh kiện tùy chọn</h3><div class="chips">${OPT_POOL.map((id) => { const t = E.clone(c); t.extras = [{ id, qty: 1 }]; const ok = E.worst(E.evalRules(t)) !== "bad"; return `<label class="chip" style="${ok ? "" : "opacity:.5"}" title="${ok ? "" : "Không tương thích với combo"}"><input type="checkbox" data-op="${cb.key}" value="${id}" ${COMBO_OPTS[cb.key].includes(id) ? "checked" : ""} ${ok ? "" : "disabled"}> ${id}</label>`; }).join("")}</div></div>`; }).join("")}</div>`,
  () => {
    $$("[data-cb]").forEach((s) => (s.onchange = () => { const cb = COMBOS.find((x) => x.key === s.dataset.cb); cb.parts[s.dataset.s] = s.value; E.log(`Đổi ${CAT[s.dataset.s]} của ${cb.name} → ${s.value}`, cb.name); rerender(); }));
    $$("[data-op]").forEach((c) => (c.onchange = () => { const k = c.dataset.op; COMBO_OPTS[k] = c.checked ? [...COMBO_OPTS[k], c.value] : COMBO_OPTS[k].filter((x) => x !== c.value); }));
  });

  // ================= SC37 – Hàng đợi yêu cầu =================
  add("SC37", "requests", "Hàng đợi yêu cầu", "UC19", "admin", () => `${head("Yêu cầu dịch vụ & hỗ trợ", "Gom lịch hẹn, bảo hành, tư vấn, khiếu nại từ web, Zalo, Facebook vào một hàng đợi. Mới → Đang xử lý → Hoàn tất (hoặc Đã hủy).", "SC37", "UC19")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Loại</th><th>Nguồn</th><th>Khách</th><th>Nội dung</th><th>Hẹn</th><th>Phân công</th><th>Trạng thái</th><th></th></tr></thead><tbody>${S.requests.map((r, i) => `<tr><td class="mono xs">${r.id}<br>${r.code}</td><td><select data-ty="${i}" style="width:auto">${["Tư vấn", "Đặt lịch", "Bảo hành", "Khiếu nại"].map((t) => `<option ${t === r.type ? "selected" : ""}>${t}</option>`).join("")}</select></td><td class="small">${esc(r.src)}</td><td><b>${esc(r.cust)}</b><br><span class="xs muted">${esc(r.phone)}</span></td><td class="small">${esc(r.what)}</td><td class="small">${esc(r.when || "—")}</td><td><select data-tc="${i}" style="width:auto"><option value="">—</option>${[...new Set(TECHS())].map((t) => `<option ${t === r.tech ? "selected" : ""}>${t}</option>`).join("")}</select></td><td><select data-st="${i}" style="width:auto">${["Mới", "Đang xử lý", "Hoàn tất", "Đã hủy"].map((t) => `<option ${t === r.st ? "selected" : ""}>${t}</option>`).join("")}</select></td><td>${r.type === "Bảo hành" ? `<button class="btn sm plain" type="button" data-rma="${i}">Mở RMA</button>` : ""}</td></tr>`).join("")}</tbody></table></div>
    <form class="panel" id="fr" style="margin-top:16px"><h3>Nhập yêu cầu từ Zalo / Facebook</h3><div class="grid4"><div class="field"><label for="rn">Khách</label><input id="rn" type="text" required></div><div class="field"><label for="rp">SĐT</label><input id="rp" type="tel" required></div><div class="field"><label for="rs">Kênh</label><select id="rs"><option>Zalo (nhân viên nhập)</option><option>Facebook (nhân viên nhập)</option><option>Gọi điện</option></select></div><div class="field"><label for="rt">Loại</label><select id="rt"><option>Tư vấn</option><option>Đặt lịch</option><option>Bảo hành</option><option>Khiếu nại</option></select></div></div><div class="field"><label for="rw">Nội dung</label><input id="rw" type="text" required></div><button class="btn sm" type="submit">Thêm vào hàng đợi</button></form>`,
  () => {
    const upd = (sel, k) => $$(sel).forEach((s) => (s.onchange = () => { const r = S.requests[+s.dataset[k]]; const f = { ty: "type", tc: "tech", st: "st" }[k]; r[f] = s.value; E.log(`Cập nhật yêu cầu (${f}) → ${s.value}`, r.id); toast("Đã cập nhật"); }));
    upd("[data-ty]", "ty"); upd("[data-tc]", "tc"); upd("[data-st]", "st");
    $$("[data-rma]").forEach((b) => (b.onclick = () => { const r = S.requests[+b.dataset.rma]; const sn = (r.what.match(/[A-Z]\w{1,2}-\d+/) || [""])[0]; S.rma.unshift({ id: "RMA-" + (302 + S.rma.length), sn: sn || "(chưa xác định)", order: "", symptom: r.what, diag: "", action: "", st: "Đang xử lý", hist: ["Mở từ yêu cầu " + r.id] }); r.st = "Đang xử lý"; go("#/rma"); }));
    $("#fr").onsubmit = (e) => { e.preventDefault(); S.requests.unshift({ id: "YC-" + (502 + S.requests.length), type: $("#rt").value, src: $("#rs").value, cust: $("#rn").value, phone: $("#rp").value, what: $("#rw").value, when: "", tech: "", st: "Mới", code: "TV-" + (1121 + S.requests.length) }); rerender(); };
  });

  // ================= SC38 – Phiếu bảo hành / RMA =================
  add("SC38", "rma", "Phiếu bảo hành / RMA", "UC19", "admin", () => `${head("Bảo hành & RMA", "Một đầu mối cho khách; BuildX khoanh vùng lỗi và đổi với NPP theo chính sách 1 đổi 1. Lịch sử lưu theo serial.", "SC38", "UC19")}
    <div class="stack" style="margin-top:12px">${S.rma.map((r, i) => { const w = S.warranties.find((x) => x.sn === r.sn); return `<div class="panel"><div class="row between"><b class="mono">${r.id} · ${esc(r.sn)}</b><select data-st="${i}" style="width:auto">${["Đang xử lý", "Chờ NPP", "Đã đổi", "Đã trả máy"].map((s) => `<option ${s === r.st ? "selected" : ""}>${s}</option>`).join("")}</select></div><p class="small muted">${r.order ? "Đơn " + r.order + " · " : ""}${w ? "Bảo hành tới " + E.dstr(new Date(w.from.getTime() + w.months * 30 * 864e5)) : "Chưa tra được phiếu bảo hành"}</p><p class="small"><b>Triệu chứng:</b> ${esc(r.symptom)}</p><div class="grid2"><div class="field"><label>Chẩn đoán</label><input type="text" data-dg="${i}" value="${esc(r.diag)}"></div><div class="field"><label>Hướng xử lý</label><input type="text" data-ac="${i}" value="${esc(r.action)}"></div></div><details><summary class="small">Lịch sử theo serial (${r.hist.length})</summary><ul class="small">${r.hist.map((h) => `<li>${esc(h)}</li>`).join("")}</ul></details></div>`; }).join("") || '<div class="empty">Chưa có phiếu RMA.</div>'}</div>`,
  () => {
    $$("[data-st]").forEach((s) => (s.onchange = () => { const r = S.rma[+s.dataset.st]; r.st = s.value; r.hist.push(E.dstr(E.TODAY) + ": " + s.value); E.log("RMA → " + s.value, r.id); rerender(); }));
    $$("[data-dg]").forEach((s) => (s.onchange = () => { const r = S.rma[+s.dataset.dg]; r.diag = s.value; r.hist.push("Chẩn đoán: " + s.value); }));
    $$("[data-ac]").forEach((s) => (s.onchange = () => { const r = S.rma[+s.dataset.ac]; r.action = s.value; r.hist.push("Xử lý: " + s.value); }));
  });

  // ================= SC39 – Mã giảm giá =================
  add("SC39", "coupons", "Mã giảm giá", "UC20", "admin", () => `${head("Mã giảm giá", "Mỗi mã có điều kiện thời gian, giá trị đơn tối thiểu và số lượt dùng; giỏ hàng kiểm tra đủ điều kiện mới áp dụng.", "SC39", "UC20")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Mã</th><th>Mô tả</th><th>Giảm</th><th>Phạm vi</th><th>Thời gian</th><th class="num">Đơn tối thiểu</th><th class="num">Đã dùng</th></tr></thead><tbody>${S.coupons.map((c) => `<tr><td class="mono">${c.code}</td><td class="small">${esc(c.desc)}</td><td>${c.type === "pct" ? c.val + "%" : fmt(c.val)}</td><td class="small">${c.scope === "pc" ? "Chỉ PC" : "Toàn đơn"}</td><td class="small">${E.dstr(c.from)} – ${E.dstr(c.to)}</td><td class="num">${fmt(c.min)}</td><td class="num">${c.used}/${c.max}</td></tr>`).join("")}</tbody></table></div>
    <form class="panel" id="fc" style="margin-top:16px"><h3>Tạo mã</h3><div class="grid4"><div class="field"><label for="cc">Mã</label><input id="cc" type="text" value="BLACKFRIDAY" required></div><div class="field"><label for="ct">Loại</label><select id="ct"><option value="pct">Phần trăm</option><option value="amt">Số tiền</option></select></div><div class="field"><label for="cv">Giá trị</label><input id="cv" type="number" value="3" required></div><div class="field"><label for="cs">Phạm vi</label><select id="cs"><option value="pc">Chỉ PC</option><option value="all">Toàn đơn</option></select></div><div class="field"><label for="cf">Từ ngày</label><input id="cf" type="date" value="2027-11-20"></div><div class="field"><label for="cu">Đến ngày</label><input id="cu" type="date" value="2027-11-30"></div><div class="field"><label for="cm">Đơn tối thiểu</label><input id="cm" type="number" value="20000000"></div><div class="field"><label for="cx">Số lượt</label><input id="cx" type="number" value="100"></div></div><div class="field"><label for="cd">Mô tả</label><input id="cd" type="text" value="Black Friday giảm 3% PC"></div><button class="btn sm" type="submit">Tạo mã</button></form>`,
  () => { $("#fc").onsubmit = (e) => { e.preventDefault(); const d = (v) => { const [y, m, dd] = v.split("-"); return new Date(+y, m - 1, +dd, 23, 59); }; S.coupons.unshift({ code: $("#cc").value.trim().toUpperCase(), desc: $("#cd").value, type: $("#ct").value, val: +$("#cv").value, scope: $("#cs").value, from: d($("#cf").value), to: d($("#cu").value), min: +$("#cm").value, max: +$("#cx").value, used: 0 }); E.log("Tạo mã giảm giá", $("#cc").value); rerender(); }; });

  // ================= SC40 – Banner & giới thiệu bạn bè =================
  add("SC40", "banners", "Banner & giới thiệu bạn bè", "UC20", "admin", () => `${head("Banner & giới thiệu bạn bè", "P2: quảng cáo trả phí chỉ chạy khi đã có lượng truy cập (khoảng tháng 6–12). Nội dung tài trợ phải ghi rõ, giữ tư vấn trung lập.", "SC40", "UC20")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Banner</th><th>Vị trí</th><th>Tài trợ</th><th class="num">Hiển thị</th><th class="num">Nhấp</th><th>Bật</th></tr></thead><tbody>${S.banners.map((b, i) => `<tr><td>${esc(b.title)}</td><td class="small">${b.place}</td><td class="small">${b.sponsor ? '<span class="pill">Nội dung tài trợ</span> ' + esc(b.sponsor) : "—"}</td><td class="num">${b.views.toLocaleString("vi-VN")}</td><td class="num">${b.clicks}</td><td><input type="checkbox" data-on="${i}" ${b.on ? "checked" : ""} aria-label="Bật banner"></td></tr>`).join("")}</tbody></table></div>
    <div class="grid2" style="margin-top:16px"><form class="panel" id="fb"><h3>Thêm banner</h3><div class="field"><label for="bt">Tiêu đề</label><input id="bt" type="text" required></div><div class="grid2"><div class="field"><label for="bp">Vị trí</label><select id="bp"><option>Trang chủ</option><option>Trang Build PC</option></select></div><div class="field"><label for="bs">Đối tác tài trợ (để trống nếu không)</label><input id="bs" type="text"></div></div><p class="xs muted">Phí tham chiếu ${fmt(5000000)}/chiến dịch; kịch bản cơ sở tính bằng 0.</p><button class="btn sm" type="submit">Thêm</button></form>
    <div class="panel"><h3>Chương trình giới thiệu bạn bè</h3><div class="grid2"><div class="field"><label for="rg">Người giới thiệu nhận</label><input id="rg" type="number" value="${S.referral.giver}"></div><div class="field"><label for="rr">Người mua nhận</label><input id="rr" type="number" value="${S.referral.receiver}"></div></div><p class="small">Từ ${S.referral.bonusFrom} người được giới thiệu: thêm ưu đãi nâng cấp linh kiện. Giả định 10% đơn PC đến từ giới thiệu, chi phí 300.000đ/đơn.</p><div class="tbl"><table><thead><tr><th>Mã</th><th>Chủ mã</th><th class="num">Đã mời</th><th class="num">Đã trả</th></tr></thead><tbody>${S.referral.list.map((r) => `<tr><td class="mono">${r.code}</td><td>${esc(r.owner)}</td><td class="num">${r.invited}</td><td class="num">${fmt(r.paid)}</td></tr>`).join("")}</tbody></table></div><button class="btn sm" type="button" id="sr" style="margin-top:8px">Lưu</button></div></div>`,
  () => {
    $$("[data-on]").forEach((c) => (c.onchange = () => { S.banners[+c.dataset.on].on = c.checked; E.log("Bật/tắt banner", S.banners[+c.dataset.on].id); }));
    $("#fb").onsubmit = (e) => { e.preventDefault(); S.banners.push({ id: "B" + (S.banners.length + 1), title: $("#bt").value, place: $("#bp").value, sponsor: $("#bs").value, on: true, views: 0, clicks: 0 }); rerender(); };
    $("#sr").onclick = () => { S.referral.giver = +$("#rg").value; S.referral.receiver = +$("#rr").value; toast("Đã lưu chương trình giới thiệu"); };
  });

  // ================= SC41 – Dashboard báo cáo =================
  add("SC41", "reports", "Dashboard báo cáo", "UC21", "admin", () => {
    const ok = S.orders.filter((o) => o.status !== "Đã hủy"), net = (v) => v / 1.1;
    let rev = { pc: 0, part: 0, svc: 0 }, cost = { pc: 0, part: 0, svc: 0 }, pcN = 0, asmN = 0, careN = 0;
    ok.forEach((o) => { const k = o.total / Math.max(1, o.sub); o.lines.forEach((l) => { if (l.type === "pc") { rev.pc += E.cfgPrice(l.cfg) * k; cost.pc += E.cfgCost(l.cfg); rev.svc += E.asmFee(l) * k; cost.svc += E.asmFee(l) ? FEES.asmCost : 0; if (l.src !== "upgrade") { pcN++; if (l.asm !== "none") asmN++; } } else if (l.type === "part") { rev.part += E.linePrice(l) * k; cost.part += byId(l.id).cost * l.qty; } else { rev.svc += l.price * k; cost.svc += FEES.careCost; careN++; } }); });
    const R = rev.pc + rev.part + rev.svc, C = cost.pc + cost.part + cost.svc, gm = R ? (1 - C / R) * 100 : 0;
    const lw = S.leads.filter((l) => l.st === "Đã chốt").length, lr = S.leads.length ? (lw / S.leads.length) * 100 : 0;
    const aged = E.units.filter((u) => u.state === "stock" && E.days(u.inDate) > 60).length;
    const top = {}; ok.forEach((o) => o.lines.filter((l) => l.type === "pc").forEach((l) => (top[l.title] = (top[l.title] || 0) + 1)));
    const maxN = Math.max(...PLAN.net) * 1.05;
    const pct = (v) => v.toLocaleString("vi-VN", { maximumFractionDigits: 1 }) + "%";
    return `${head("Báo cáo", "Số liệu tính từ đơn trong hệ thống (dữ liệu mẫu tháng 1 sau khai trương) so với kế hoạch v3. Doanh thu thuần = gộp ÷ 1,1.", "SC41", "UC21")}
    <div class="grid4" style="margin-top:12px"><div class="kpi"><div class="lbl">Doanh thu thuần (tháng này)</div><div class="v">${tr(net(R))} tr</div><div class="d">Kế hoạch T1: ${PLAN.net[0].toLocaleString("vi-VN")} tr</div></div><div class="kpi"><div class="lbl">Biên lãi gộp</div><div class="v">${pct(gm)}</div><div class="d">Mục tiêu ≥ ${PLAN.kpi.margin}%; cảnh báo &lt; ${PLAN.kpi.marginAlert}%</div></div><div class="kpi"><div class="lbl">Số bộ PC</div><div class="v">${pcN}</div><div class="d">Kế hoạch T1: ${PLAN.pc[0]} · hòa vốn ~${PLAN.kpi.breakeven}/tháng</div></div><div class="kpi"><div class="lbl">Lead → đơn</div><div class="v">${pct(lr)}</div><div class="d">Giả định ${PLAN.kpi.leadOrder}%</div></div>
    <div class="kpi"><div class="lbl">Tỷ lệ chọn lắp ráp</div><div class="v">${pct(pcN ? (asmN / pcN) * 100 : 0)}</div><div class="d">Giả định ${PLAN.kpi.asm}%</div></div><div class="kpi"><div class="lbl">Tỷ lệ mua Care</div><div class="v">${pct(pcN ? (careN / pcN) * 100 : 0)}</div><div class="d">Giả định ${PLAN.kpi.care}%</div></div><div class="kpi"><div class="lbl">Serial tồn &gt; 60 ngày</div><div class="v">${aged}</div><div class="d">Theo dõi hằng tuần</div></div><div class="kpi"><div class="lbl">Đơn đang mở</div><div class="v">${S.orders.filter((o) => !["Hoàn tất", "Đã hủy"].includes(o.status)).length}</div><div class="d">${S.orders.filter((o) => o.status === "Chờ hàng").length} chờ hàng</div></div></div>
    <div class="grid2" style="margin-top:16px"><div class="panel"><h3>Doanh thu & biên gộp theo nhóm</h3><div class="tbl"><table><thead><tr><th>Nhóm</th><th class="num">DT thuần</th><th class="num">Biên gộp</th></tr></thead><tbody>${[["PC trọn bộ", "pc"], ["Linh kiện lẻ", "part"], ["Dịch vụ & Care", "svc"]].map(([l, k]) => `<tr><td>${l}</td><td class="num">${fmt(net(rev[k]))}</td><td class="num">${rev[k] ? pct((1 - cost[k] / rev[k]) * 100) : "—"}</td></tr>`).join("")}</tbody></table></div><h3 style="margin-top:12px">Cấu hình bán nhiều nhất</h3><ol class="small">${Object.entries(top).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, v]) => `<li>${esc(k)} – ${v}</li>`).join("")}</ol></div>
    <div class="panel"><h3>Kế hoạch doanh thu thuần 12 tháng (triệu đồng)</h3><div class="legend"><span><i style="background:var(--line)"></i>Kế hoạch</span><span><i style="background:var(--accent)"></i>Thực tế</span></div><div class="bar">${PLAN.net.map((v, i) => `<div><span class="pair"><b class="plan" style="height:${(v / maxN) * 100}%" title="Kế hoạch ${PLAN.months[i]}: ${v} tr"></b>${i === 0 ? `<b style="height:${Math.min(100, (net(R) / 1e6 / maxN) * 100)}%" title="Thực tế T1: ${tr(net(R))} tr"></b>` : ""}</span><span>${PLAN.months[i]}</span></div>`).join("")}</div><p class="xs muted">EBT kế hoạch: lỗ đến T7, có lãi từ T8 (+1,4 tr), T12 +42,2 tr. Ngưỡng cảnh báo: 3 tháng liền &lt; 80% kế hoạch hoặc biên &lt; 13%.</p><button class="btn sm plain" type="button" id="csv">Xuất Excel (CSV)</button></div></div>`;
  }, () => {
    $("#csv").onclick = () => { const rows = [["Mã đơn", "Ngày", "Kênh", "Khách", "Trạng thái", "Thanh toán", "Tổng"]].concat(S.orders.map((o) => [o.id, E.dstr(o.date), o.channel, o.cust.name, o.status, o.pay.status, o.total])); const csv = "﻿" + rows.map((r) => r.map((x) => `"${String(x).replace(/"/g, '""')}"`).join(",")).join("\n"); const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); a.download = "buildx-bao-cao.csv"; a.click(); toast("Đã xuất CSV"); };
  });

  // ================= SC42 – Tài khoản nhân viên & vai trò =================
  const hash = (s) => { let h = 2166136261; for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16).padStart(8, "0"); };
  add("SC42", "users", "Tài khoản nhân viên & vai trò", "UC22", "admin", () => `${head("Người dùng & phân quyền", "Mỗi người chỉ thấy chức năng đúng vai trò (đổi 'Vai trò demo' ở góc trên để thử). Mật khẩu lưu bằng hàm băm; thao tác với giá, kho, hoàn tiền được lưu vết.", "SC42", "UC22")}
    <div class="tbl" style="margin-top:12px"><table><thead><tr><th>Tên</th><th>Email</th><th>Vai trò</th><th>Màn hình được mở</th><th>Trạng thái</th></tr></thead><tbody>${S.staffUsers.map((u, i) => `<tr><td>${esc(u.name)}</td><td class="small">${esc(u.email)}</td><td><select data-r="${i}" style="width:auto">${Object.keys(ROLES).map((r) => `<option ${r === u.role ? "selected" : ""}>${r}</option>`).join("")}</select></td><td class="xs">${ROLES[u.role].includes("*") ? "Tất cả" : ROLES[u.role].filter((p) => A.SCREENS.find((s) => s.path === p)).map((p) => A.SCREENS.find((s) => s.path === p).code).join(", ")}</td><td><button class="btn sm ${u.on ? "plain" : "danger"}" type="button" data-l="${i}">${u.on ? "Hoạt động · Khóa" : "Đã khóa · Mở"}</button></td></tr>`).join("")}</tbody></table></div>
    <form class="panel" id="fu" style="margin-top:16px"><h3>Tạo tài khoản</h3><div class="grid4"><div class="field"><label for="un">Tên</label><input id="un" type="text" required></div><div class="field"><label for="ue">Email</label><input id="ue" type="email" required></div><div class="field"><label for="ur">Vai trò</label><select id="ur">${Object.keys(ROLES).map((r) => `<option>${r}</option>`).join("")}</select></div><div class="field"><label for="up">Mật khẩu tạm</label><input id="up" type="password" value="BuildX@2027" required></div></div><button class="btn sm" type="submit">Tạo</button><p class="xs muted" id="hh"></p></form>
    <div class="panel" style="margin-top:16px"><h3>Nhật ký thao tác nhạy cảm</h3>${S.log.slice(0, 10).map((l) => `<div class="small"><span class="mono xs muted">${E.tstr(l.t)}</span> · ${esc(l.who)}: ${esc(l.action)} <span class="mono xs">${esc(l.target)}</span></div>`).join("")}</div>`,
  () => {
    $$("[data-r]").forEach((s) => (s.onchange = () => { const u = S.staffUsers[+s.dataset.r]; u.role = s.value; E.log(`Đổi vai trò ${u.name} → ${s.value}`, u.email); rerender(); }));
    $$("[data-l]").forEach((b) => (b.onclick = () => { const u = S.staffUsers[+b.dataset.l]; u.on = !u.on; E.log((u.on ? "Mở khóa " : "Khóa ") + u.name, u.email); rerender(); }));
    $("#fu").onsubmit = (e) => { e.preventDefault(); const h = hash($("#up").value + $("#ue").value); S.staffUsers.push({ name: $("#un").value, email: $("#ue").value, role: $("#ur").value, on: true, pw: h }); E.log("Tạo tài khoản nhân viên", $("#ue").value); rerender(); toast("Đã tạo; mật khẩu lưu dạng băm " + h + "… (demo)"); };
  });

  A.start();
})();
